# محتوى الحزب السابع H07 — العناوين والتدبر والمحطات (صياغة أصلية للمراجعة)

F7 = "٠٧ - الحزب السابع - تفسير السعدي.pdf"
F6 = "٠٦ - الحزب السادس - تفسير السعدي.pdf"
FQ = "04_القرآن تدبر وعمل.pdf"

SAADI_92 = [
    "هذا حث من الله لعباده على الإنفاق في طرق الخيرات، فقال {لن تنالوا} أي: تدركوا وتبلغوا البر الذي هو كل خير من أنواع الطاعات وأنواع المثوبات الموصل لصاحبه إلى الجنة، {حتى تنفقوا مما تحبون} أي: من أموالكم النفيسة التي تحبها نفوسكم، فإنكم إذا قدمتم محبة الله على محبة الأموال فبذلتموها في مرضاته، دل ذلك على إيمانكم الصادق وبر قلوبكم ويقين تقواكم، فيدخل في ذلك إنفاق نفائس الأموال، والإنفاق في حال حاجة المنفق إلى ما أنفقه، والإنفاق في حال الصحة، ودلت الآية أن العبد بحسب إنفاقه للمحبوبات يكون بره، وأنه ينقص من بره بحسب ما نقص من ذلك، ولما كان الإنفاق على أي: وجه كان مثابا عليه العبد، سواء كان قليلا أو كثيرا، محبوبا للنفس أم لا وكان قوله {لن تنالوا البر حتى تنفقوا مما تحبون} مما يوهم أن إنفاق غير هذا المقيد غير نافع، احترز تعالى عن هذا الوهم بقوله {وما تنفقوا من شيء فإن الله به عليم} فلا يضيق عليكم، بل يثيبكم عليه على حسب نياتكم ونفعه."
]

# (id, verses, title, tadabbur paragraphs, question)
CARDS = {
"C001": ("92", "البرّ يُنال بما تحبّ", [
 "تجعل الآية البرَّ غايةً تُطلَب، وتربط بلوغها بالبذل من المحبوب لا من الفائض. فالسؤال الذي تضعه أمام القلب ليس: كم أعطيت؟ بل: ماذا قدّمتُ حين تزاحم ما أحبّه مع ما يحبّه الله؟",
 "ثم تأتي خاتمتها فتحفظ الباب مفتوحًا: {وما تنفقوا من شيء فإن الله به عليم}؛ فلا يضيع عند الله إنفاقٌ قلّ أو كثر. هكذا ترفع الآية الهمّة، ولا تُيئس من دون ذلك."],
 "ما الشيء الذي أحبّه، ويمكن أن يكون بابي إلى البرّ؟"),
"C002": ("93-95", "الحجّة من الكتاب نفسه", [
 "حين نشأ الجدل في الحلال والحرام لم تُقابَل الدعوى بدعوى، بل بطلب البيّنة من الكتاب الذي يقرّ به المخالف: {فأتوا بالتوراة فاتلوها}. وفي هذا أدبٌ في الحِجاج: أن يُحتكَم إلى ما يُسلّمه الطرف الآخر.",
 "ثم يسمّي النصُّ من افترى على الله الكذب بعد قيام البيّنة ظالمًا؛ فالخلل عندئذ ليس في نقص الدليل بل في ردّه. ويُختم الموقف بأمرين متلازمين: {قل صدق الله} ثم {فاتبعوا ملة إبراهيم حنيفا}؛ فالتصديق يُتبَع باتّباع."],
 "حين يتبيّن لي الحقّ في مسألة، هل أتّبعه أم أبحث عمّا يُعفيني منه؟"),
"C003": ("96-97", "بيتٌ يهدي، وفريضةٌ بقدر الاستطاعة", [
 "وصف الله البيت قبل أن يذكر فريضته: أوّلُ بيتٍ وُضع للناس، مباركٌ، هدى للعالمين، فيه آيات بيّنات، ومن دخله كان آمنًا. فالقلب يُعرَّف بقدر الشيء قبل أن يُكلَّف به، كما نبّه ابن القيّم في النقل الذي أورده السعدي.",
 "ثم جاء الوجوب مقرونًا بالاستطاعة: {من استطاع إليه سبيلا}، وخُتمت الآية بغنى الله عن العالمين؛ فالطاعة لا تزيد في ملكه شيئًا، والمنتفع بها هو العبد."],
 "هل أتعامل مع الطاعات أثقالًا مفروضة، أم أتعرّف إلى قدرها فتقوى رغبتي فيها؟"),
"C004": ("98-100", "لمن أُسلِم زمام التوجيه؟", [
 "تبدأ الآيات بسؤالين لأهل الكتاب: لِمَ تكفرون بآيات الله؟ ولِمَ تصدّون عن سبيله؟ مع التذكير بأن الله شهيد على ما يعملون وليس بغافل عنه.",
 "ثم تلتفت إلى المؤمنين بتحذيرٍ محدّد: إن تطيعوا {فريقًا} من الذين أوتوا الكتاب — لا جميعهم — يردّوكم بعد إيمانكم كافرين. فمحلّ التحذير هنا هو الطاعة والانقياد لمن هذا حاله؛ والسعدي يعلّل ذلك بحسدهم وحرصهم على ردّ المؤمنين عن دينهم."],
 "لمن أمنح زمام التوجيه في ديني وقيمي؟ وهل أعرف غايته قبل أن أتّبعه؟"),
"C005": ("101", "الاعتصام طريقٌ إلى الصراط", [
 "يقوم استنكار {وكيف تكفرون} على حضور سببين عظيمين للثبات: آيات الله تُتلى، والرسول ﷺ بين أظهرهم. ويبقى لكل مؤمن نصيبٌ من هذين السببين ما دام يتلو كتاب الله ويتّبع سنّة رسوله ﷺ.",
 "ثم تقرّر الآية قاعدة: {ومن يعتصم بالله فقد هُدي إلى صراط مستقيم}. والاعتصام — كما بيّنه السعدي — توكّلٌ على الله، وامتناعٌ بقوته من كل شر، واستعانةٌ به على كل خير."],
 "ما نصيب آيات الله المتلوّة من يومي؟ وبمن أعتصم حين أضطرب؟"),
"C006": ("102-103", "تقوى إلى الخاتمة، وحبلٌ يجمع", [
 "أمرٌ بالتقوى {حق تقاته}، ثم نهيٌ عن الموت إلا على الإسلام. ولأن وقت الموت لا يُعلَم، فالمعنى العملي أن تكون الاستقامة حالًا دائمة؛ وقد قرّر السعدي أن من عاش على شيء مات عليه.",
 "ثم ينتقل الخطاب من الفرد إلى الجماعة: {واعتصموا بحبل الله جميعا ولا تفرقوا}، ويذكّر بنعمة التأليف بعد العداوة، وينسبه إلى الله: {فألّف بين قلوبكم}. فالأُلفة نعمةٌ تُذكَر وتُشكَر، لا إنجازٌ يُنسب إلى الأنفس."],
 "أين أحتاج أن أُصلح ما بيني وبين أخٍ لي، وأسأل الله أن يؤلّف بين القلوب؟"),
"C007": ("104-105", "أمّةٌ تدعو، وحذرٌ من التفرّق بعد البيّنة", [
 "{ولتكن منكم أمة}: طلبٌ بأن توجد في المؤمنين جماعةٌ قائمة بالدعوة إلى الخير والأمر بالمعروف والنهي عن المنكر، وقد وصفهم الله بالفلاح. وذكر السعدي أن هذه الأمور من فروض الكفايات، وأن ما لا تتمّ إلا به مأمورٌ به.",
 "ثم يأتي التحذير من حال الذين تفرّقوا واختلفوا {من بعد ما جاءهم البينات}؛ فالخلل الذي تكشفه الآية ليس غياب البيان، بل ترك الاعتصام به بعد مجيئه."],
 "ما الدور الممكن لي — بقدر علمي واستطاعتي — في دعوةٍ إلى خير، أو عونٍ لمن يقوم بها؟"),
"C008": ("106-108", "يومٌ تظهر فيه الحقائق", [
 "تنقل الآيات المشهد إلى يوم القيامة: وجوهٌ تبيضّ ووجوهٌ تسودّ. وربط السعدي بين بياض الوجوه وأهل الائتلاف والاعتصام بحبل الله، وبين سوادها وأهل الفرقة والاختلاف.",
 "ثم تُختم الآيات بتقرير العدل: {وما الله يريد ظلما للعالمين}؛ فالجزاء ليس انتقامًا، بل عدلٌ وفضل."],
 "ما الذي أرجو أن يظهر من قلبي يوم تظهر الحقائق؟ وماذا أصلح اليوم لأجله؟"),
"C009": ("109", "إليه تُرجَع الأمور", [
 "آيةٌ قصيرة تضع ما قبلها في إطاره: لله ما في السماوات وما في الأرض، وإليه تُرجع الأمور. فالأمر والنهي والوعد والوعيد صادرةٌ عمّن يملك ويجازي."],
 "أيّ أمرٍ يشغلني اليوم أحتاج أن أتذكّر أن مرجعه إلى الله؟"),
"C010": ("110-112", "خيريّةٌ مقرونة بأوصاف", [
 "{كنتم خير أمة أخرجت للناس} خبرٌ جاء مقرونًا بأوصاف: تأمرون بالمعروف، وتنهون عن المنكر، وتؤمنون بالله. وفسّر السعدي هذه الخيرية بتكميل النفس بالإيمان، وتكميل الغير بالأمر والنهي.",
 "ثم تبيّن الآيات أن ما يصيب المؤمنين من أولئك في هذا السياق {أذى} لا يبلغ الضرر في الدين، وتذكر سبب ما حلّ بمن كفر بالآيات وقتل الأنبياء: {ذلك بما عصوا وكانوا يعتدون}؛ فالمعصية والاعتداء طريقٌ يجرّ إلى ما هو أعظم منه."],
 "أيّ هذه الأوصاف الثلاثة أحتاج أن أقوّيه في نفسي؟"),
"C011": ("113-115", "ليسوا سواءً", [
 "بعد ذكر الفريق الفاسق يأتي الإنصاف: {ليسوا سواء}. فالقرآن لا يعمّم الحكم على جماعةٍ بأسرها، ويذكر أهل الاستقامة بأوصافهم: قيامٌ بالليل وتلاوة، وإيمانٌ بالله واليوم الآخر، وأمرٌ ونهي، ومسارعة في الخيرات.",
 "ثم وعدٌ بألّا يُجحد عملهم: {وما يفعلوا من خير فلن يكفروه}؛ وقيّد السعدي ذلك بما يقوم في القلب من الإيمان والتقوى: {والله عليم بالمتقين}."],
 "هل أنصف في حكمي على الناس، أم أعمّم بسبب بعضهم؟"),
"C012": ("116-117", "ريحٌ فيها صِرّ", [
 "تقرّر الآيات أن الأموال والأولاد لا تغني عن الذين كفروا من الله شيئًا. ثم تضرب مثلًا لما ينفقونه: زرعٌ رُجي حصاده، فأصابته ريحٌ شديدة البرد فأهلكته؛ فبطل العمل الذي لم يقم على الإيمان.",
 "وتُختم الآية بإعادة المسؤولية إلى أصحابها: {وما ظلمهم الله ولكن أنفسهم يظلمون}."],
 "على أيّ أساس أبني ما أعمل وأنفق؟"),
"C013": ("118-120", "لمن تفتح سرّك؟", [
 "تنهى الآيات عن اتخاذ {بطانة من دونكم} ممّن بدت البغضاء من أفواههم، وذكر السعدي أنهم المنافقون من أهل الكتاب وغيرهم. والبطانة كما يُفهم من كلامه: من يُطلَع على السرائر ويُولّى بعض الأعمال. وجعل السعدي العاقلَ من إذا اضطُرّ إلى مخالطة العدو كانت مخالطته في الظاهر دون أن يطلعه على باطنه.",
 "ثم تضع الآيات منهج التعامل مع كيدهم: {وإن تصبروا وتتقوا لا يضركم كيدهم شيئا}؛ فالعلاج هنا صبرٌ وتقوى، لا انفعالٌ ولا مجاراة."],
 "هل أضع ثقتي في مواضعها؟ وهل أقابل الكيد بالصبر والتقوى؟"),
"C014": ("121", "تذكّر النعمة عند المكروه", [
 "يبدأ سياق غزوة أُحد بمشهد النبي ﷺ يبوّئ المؤمنين مقاعدهم للقتال. وذكر السعدي من حكمة الجمع بين قصّتي بدر وأحد أن الله يحبّ من عباده إذا أصابهم ما يكرهون أن يتذكّروا ما يحبّون، فيخفّ عنهم البلاء.",
 "وتُختم الآية بـ{والله سميع عليم}: يسمع ما يقوله كلٌّ بحسب ما في قلبه، ويعلم النيّات."],
 "حين يصيبني ما أكره، هل أستحضر ما سبق من نعم الله عليّ؟"),
"C015": ("122", "همٌّ لم يتمّ، وولايةٌ حفظت", [
 "همّت طائفتان من المؤمنين أن تفشلا، والله وليّهما فثبّتهما. فالآية تفرّق بين خاطرٍ يعرض وفعلٍ يقع، وتنسب العصمة من الانهيار إلى ولاية الله الخاصّة لأوليائه، كما بيّن السعدي.",
 "ثم تأمر: {وعلى الله فليتوكل المؤمنون}؛ والتوكّل — كما عرّفه السعدي — اعتماد القلب على الله في جلب المنافع ودفع المضار مع الثقة به."],
 "حين يعرض لي الضعف، إلى من ألجأ أولًا؟"),
"C016": ("123-126", "الأسباب بشرى، والنصر من عند الله", [
 "تذكّر الآيات بنصر بدر والمؤمنون أذلّة في قلّة العدد والعُدد، ثم تذكر وعد الإمداد بخمسة آلاف من الملائكة، وقد فصّل السعدي شروطه الثلاثة: الصبر، والتقوى، وإتيان المشركين من فورهم ذلك.",
 "ثم تحدّد وظيفة الإمداد: {وما جعله الله إلا بشرى لكم ولتطمئن قلوبكم به}، وتحصر مصدر النصر: {وما النصر إلا من عند الله العزيز الحكيم}. فالأسباب مطلوبة، لكن القلب لا يعتمد عليها."],
 "على ماذا يطمئن قلبي حين آخذ بالأسباب؟"),
"C017": ("127", "صورٌ للنصر", [
 "تذكر الآية غايتين للنصر: أن يقطع الله طرفًا من الذين كفروا، أو يكبتهم فينقلبوا خائبين. وقرّر السعدي أن نصر الله لعباده المؤمنين دائرٌ بين هذين الأمرين.",
 "فالنصر قد يأتي في صورة ذهاب بعض قوّة المعتدي، وقد يأتي في صورة ردّه خائبًا دون أن يبلغ مقصوده."],
 "هل أحصر النصر في صورةٍ واحدة أتوقّعها؟"),
"C018": ("128-129", "ليس لك من الأمر شيء", [
 "خطابٌ للنبي ﷺ في أشدّ المواقف: {ليس لك من الأمر شيء}. وقرّر السعدي أنه إذا كان هذا للرسول ﷺ فغيره من باب أولى، وأن في ذلك ردًّا على من تعلّق بالأنبياء أو الصالحين فيما لا يملكه إلا الله.",
 "ونبّه السعدي إلى أن التوبة أُسندت إلى الله دون ذكر سببٍ منهم، دلالةً على أنها محض فضل، وأن العذاب ذُكر معه ظلمهم. ثم خُتمت الآيات باسمين دالّين على الرحمة: {والله غفور رحيم}."],
 "هل أعلّق قلبي بأحدٍ من الخلق فيما لا يملكه إلا الله؟"),
"C019": ("130-132", "من خصال التقوى: ترك الظلم في المال", [
 "يرى السعدي أن إدخال هذه الآيات أثناء قصة أحد — والله أعلم — لبيان خصال التقوى التي وُعد عليها بالنصر. وأوّل ما ذُكر النهي عن أكل الربا أضعافًا مضاعفة؛ وبيّن السعدي أن في هذا الوصف تنبيهًا على شناعته، وعلى حكمة تحريمه وهي ما فيه من الظلم.",
 "ثم أمرٌ بتقوى الله، وتقوى النار، وطاعة الله والرسول {لعلكم ترحمون}."],
 "هل في معاملاتي ما يُثقل على محتاجٍ أو معسر؟"),
"C020": ("133-136", "سارِعوا… وهذه صفات المتقين", [
 "{وسارعوا} فعلُ حركة لا انتظار. ثم تصف الآيات المتقين: ينفقون في السرّاء والضرّاء، ويكظمون الغيظ، ويعفون عن الناس، ويحسنون.",
 "ثم تذكر حالهم إذا وقعوا في الذنب: {ذكروا الله فاستغفروا لذنوبهم… ولم يصروا على ما فعلوا وهم يعلمون}. فالمتّقي في هذه الآيات ليس من لا يخطئ، بل من يرجع ولا يُصرّ."],
 "أيّ هذه الخصال أبدأ به اليوم؟"),
"C021": ("137-138", "سُنَنٌ خلت من قبلكم", [
 "{قد خلت من قبلكم سنن}: فأحوال الأمم الماضية ليست حكاياتٍ للتسلية، بل بيان. والأمر {فسيروا في الأرض فانظروا} يجمع — كما قال السعدي — السير بالأبدان والقلوب.",
 "ثم تحدّد الآية من ينتفع: {هذا بيان للناس وهدى وموعظة للمتقين}؛ فالبيان عامّ، والانتفاع لأهل التقوى."],
 "ما العبرة التي أقرؤها في أحداثٍ مرّت بي أو بمن حولي؟"),
"C022": ("139-140", "لا تهنوا ولا تحزنوا", [
 "نهيٌ عن الوهن في الأبدان والحزن في القلوب بعد المصيبة، مع تذكير: {وأنتم الأعلون إن كنتم مؤمنين}؛ فالعلوّ هنا مشروطٌ بالإيمان.",
 "ثم مواساة: القرح أصاب الفريقين، والأيام دولٌ بين الناس. وذكر السعدي من حِكم ذلك أن يتبيّن المؤمن من المنافق، وأن يتّخذ الله من المؤمنين شهداء."],
 "كيف أقرأ مصيبتي: نهايةً، أم يومًا من أيامٍ يداولها الله؟"),
"C023": ("141-143", "التمحيص والطريق إلى الجنة", [
 "من حِكم الابتلاء التمحيص: {وليمحص الله الذين آمنوا}. ثم يأتي استفهامٌ إنكاري: {أم حسبتم أن تدخلوا الجنة ولما يعلم الله الذين جاهدوا منكم ويعلم الصابرين}؛ فالمطلوب العظيم له طريقٌ فيه مشقّة.",
 "ثم عتابٌ لمن تمنّى لقاء العدو قبل وقوعه، فلما رآه لم يصبر كما ينبغي. واستفاد السعدي من الآية أن تمنّي الشهادة لا يُكره، وأن الإنكار وقع على عدم العمل بمقتضى الأمنية."],
 "هل أطلب غاياتٍ عالية دون استعدادٍ لمشقّتها؟"),
"C024": ("144-145", "ثباتٌ لا يتعلّق بشخص", [
 "{وما محمد إلا رسول قد خلت من قبله الرسل}: فعبادة الله لا تتوقّف على بقاء أحد. واستفاد السعدي منها أن تستعدّ الأمة في كل أمرٍ من أمور الدين بأهل الكفاءة، حتى لا يزعزعها فقدُ رئيسٍ ولو عظم.",
 "ثم تقرّر الآيات أن الآجال بيد الله {كتابا مؤجلا}، وأن الله يعطي من ثواب الدنيا والآخرة بحسب ما تعلّقت به الإرادات، ويجزي الشاكرين."],
 "هل التزامي قائمٌ على الله، أم مرتبطٌ بأشخاصٍ إن غابوا ضعف؟"),
"C025": ("146-148", "ربّيّون لم يهنوا", [
 "نموذجٌ من أتباع الأنبياء: {فما وهنوا لما أصابهم في سبيل الله وما ضعفوا وما استكانوا}.",
 "ثم تذكر الآيات ما قالوه في الشدّة: استغفارٌ من الذنوب والإسراف، وطلبُ تثبيتٍ ونصر. وبيّن السعدي أنهم جمعوا بين الصبر والتوبة والاستنصار بالله، وعلموا أن الذنوب من أسباب الخذلان."],
 "في شدّتي، هل أبدأ بمراجعة نفسي والاستغفار قبل طلب الفرج؟"),
"C026": ("149-151", "بل الله مولاكم", [
 "تحذيرٌ من طاعة الذين كفروا، لأنها تردّ على الأعقاب فتنقلبوا خاسرين. وبديلها: {بل الله مولاكم وهو خير الناصرين}.",
 "ثم تبيّن الآيات أن الرعب يُلقى في قلوب الذين كفروا {بما أشركوا بالله ما لم ينزل به سلطانا}؛ وربط السعدي بين الشرك والرعب، لأن المشرك لا يعتمد على ركنٍ وثيق."],
 "من أتولّى حقًّا؟ وأين أبحث عن الأمان؟"),
"C027": ("152", "صدق الوعد، وموضع الخلل", [
 "تبدأ الآية بتقرير أن الله صدق وعده، ثم تحدّد نقطة التحوّل: {حتى إذا فشلتم وتنازعتم في الأمر وعصيتم من بعد ما أراكم ما تحبون}.",
 "ثم تكشف تفاوت الإرادات: {منكم من يريد الدنيا ومنكم من يريد الآخرة}، وتُختم بالعفو والفضل: {ولقد عفا عنكم والله ذو فضل على المؤمنين}."],
 "حين يتغيّر حالي، هل أراجع التنازع والمعصية وما تريده نفسي؟"),
"C028": ("153", "غمٌّ بغمّ… لكيلا تحزنوا", [
 "تصوّر الآية لحظة الانهزام والرسول ﷺ يدعوهم في أُخراهم. ثم {فأثابكم غما بغم لكيلا تحزنوا على ما فاتكم ولا ما أصابكم}.",
 "وذكر السعدي في معنى {لكيلا تحزنوا} وجهين: أن الغمّ الأكبر هوّن ما دونه لما تبيّن لهم أن الرسول ﷺ لم يُقتل، أو أن ذلك الغمّ قُدِّر ليتمرّنوا على الصبر على المصيبات."],
 "هل يمكن أن يكون في غمٍّ مرّ بي تمرينٌ على الصبر؟"),
"C029": ("154", "أمنةٌ نعاسًا، وظنٌّ بغير الحق", [
 "بعد الغمّ صار الناس طائفتين: طائفةٌ أنزل الله عليها النعاس أمنة، وطائفةٌ أهمّتهم أنفسهم فظنّوا بالله غير الحق. وجاء الردّ: {قل إن الأمر كله لله}.",
 "ثم تكشف الآية غايةً من غايات ما جرى: {وليبتلي الله ما في صدوركم وليمحص ما في قلوبكم}. وهذه الآية من أوضح شواهد هذا الحزب على صلة الأحداث بما في الصدور."],
 "عند المصيبة، أيّ ظنٍّ بالله يغلب على قلبي؟"),
"C030": ("155", "مدخل الشيطان", [
 "الذين تولّوا يوم التقى الجمعان {إنما استزلهم الشيطان ببعض ما كسبوا}. وبيّن السعدي أن الذنوب مركب الشيطان ومدخله، وأنهم لو اعتصموا بطاعة ربهم لما كان له عليهم سلطان.",
 "ثم {ولقد عفا الله عنهم إن الله غفور حليم}؛ فباب التوبة مفتوح بعد الزلّة."],
 "هل هناك ذنبٌ صغير قد يكون مدخلًا لزلّةٍ أكبر؟"),
"C031": ("156-157", "حسرة «لو»", [
 "نهيٌ عن مشابهة الذين كفروا في قولهم لإخوانهم: {لو كانوا عندنا ما ماتوا وما قتلوا}. وبيّن السعدي أن هذا القول لا يردّ قدرًا، وأن الله يجعله حسرةً في قلوبهم، أما المؤمنون فيعلمون أن ذلك بقدر الله فيسلّمون، فيهدي الله قلوبهم.",
 "ثم تقرّر الآية أن مغفرة الله ورحمته خيرٌ ممّا يجمعه أهل الدنيا."],
 "هل أعيش بعد ما قُدِّر في حسرة «لو»، أم أسلّم وأسأل الله الهداية؟"),
"C032": ("158", "المرجع واحد", [
 "موتٌ أو قتل — المرجع إلى الله. ونبّه السعدي إلى أن هذا يجعل الفرار إلى الله وحده، والاعتصام بحبله هو العاصم."],
 "هل أستحضر أن كل طريقٍ ينتهي إلى الله؟"),
"C033": ("159", "لينٌ من رحمة الله", [
 "لِينُ النبي ﷺ لأصحابه رحمةٌ من الله، ولو كان فظًّا غليظ القلب لانفضّوا من حوله. وقرّر السعدي أن الأخلاق الحسنة من الرئيس في الدين تجذب الناس إلى دين الله، وأن السيئة تنفّر.",
 "ثم أوامر متتابعة: اعفُ عنهم، واستغفر لهم، وشاورهم في الأمر، فإذا عزمت فتوكّل على الله. وذكر السعدي من فوائد المشاورة أنها عبادة، وتطييبٌ للخواطر، وإعمالٌ للأفكار، وطريقٌ إلى الرأي المصيب."],
 "في موقع مسؤوليتي — بيتًا أو عملًا أو جماعة — هل يجتمع الناس حولي أم ينفضّون؟ وهل أشاور قبل أن أعزم؟"),
"C034": ("160", "النصر والخذلان بيد الله", [
 "{إن ينصركم الله فلا غالب لكم وإن يخذلكم فمن ذا الذي ينصركم من بعده}. ثم {وعلى الله فليتوكل المؤمنون}، وبيّن السعدي أن تقديم {وعلى الله} يؤذن بالحصر: على الله لا على غيره."],
 "على من أعتمد حقًّا حين أخطّط وأعمل؟"),
"C035": ("161", "الأمانة تُحمَل إلى يوم القيامة", [
 "تنزّه الآية النبيّ ﷺ عن الغلول، ثم تذكر الوعيد: {ومن يغلل يأت بما غل يوم القيامة}. وعرّف السعدي الغلول بأنه الكتمان من الغنيمة، والخيانة في كل مال يتولّاه الإنسان.",
 "ثم {ثم توفى كل نفس ما كسبت وهم لا يظلمون}؛ ونبّه السعدي إلى أن اللفظ جاء عامًّا لكل عامل، لا للغالّ وحده."],
 "هل تحت يدي مالٌ أو أمانةٌ أحتاج إلى مراجعة أدائها؟"),
"C036": ("162-163", "لا يستويان", [
 "{أفمن اتبع رضوان الله كمن باء بسخط من الله}: استفهامٌ يقرّر عدم الاستواء. ثم {هم درجات عند الله}؛ فالتفاوت بحسب الأعمال، والله بصيرٌ بما يعملون."],
 "في قراري القادم: هل أتحرّى رضوان الله، أم ما يُرضي نفسي؟"),
"C037": ("164", "أعظم المنّة", [
 "يمتنّ الله على المؤمنين ببعثة رسولٍ منهم: يتلو عليهم آياته، ويزكّيهم، ويعلّمهم الكتاب والحكمة. وسمّى السعدي هذه المنّة أكبر النعم بل أصلها.",
 "وتلفت الآية إلى أن التزكية جاءت بين التلاوة والتعليم؛ فالمقصود أن يتحوّل ما يُتلى ويُتعلَّم إلى طهارةٍ في النفس."],
 "هل آخذ من هذه المنّة التلاوة وحدها، أم أطلب التزكية والتعلّم أيضًا؟"),
"C038": ("165", "قل هو من عند أنفسكم", [
 "عند السؤال {أنّى هذا} يأتي الجواب: {قل هو من عند أنفسكم}. وبيّن السعدي أن ذلك حين تنازعوا وعصوا، فأمرهم أن يعودوا على أنفسهم باللوم ويحذروا الأسباب المردية.",
 "ثم {إن الله على كل شيء قدير}؛ وفسّرها السعدي بالتحذير من سوء الظن بالله، فهو قادرٌ على نصرهم، وله الحكمة في ابتلائهم."],
 "حين يصيبني ما أكره، هل أبدأ بمراجعة نفسي قبل البحث عن سببٍ خارجها؟"),
"C039": ("166-168", "ما أصابكم فبإذن الله… وليعلم", [
 "ما أصابهم يوم التقى الجمعان فبإذن الله، ومن حكمته أن يتميّز المؤمنون ممّن نافق. ووصفت الآيات الذين نافقوا: يقولون بأفواههم ما ليس في قلوبهم، والله أعلم بما يكتمون.",
 "ثم جاء الرد على من قال: {لو أطاعونا ما قتلوا}: {قل فادرءوا عن أنفسكم الموت إن كنتم صادقين}. واستفاد السعدي من الآيات أن العبد قد تجتمع فيه خصلةُ كفر وخصلةُ إيمان، ويكون إلى إحداهما أقرب."],
 "هل يطابق ما أقوله ما في قلبي؟"),
"C040": ("169-170", "أحياءٌ عند ربهم", [
 "نهيٌ عن حسبان الذين قُتلوا في سبيل الله أمواتًا: {بل أحياء عند ربهم يرزقون}، فرحين بما آتاهم الله من فضله، ويستبشرون بالذين لم يلحقوا بهم.",
 "وذكر السعدي أن في هذه الآيات تسليةً للأحياء عن قتلاهم، وإثباتًا لنعيم البرزخ. فالفقد في سبيل الله ليس نهاية، بل انتقالٌ إلى فضل الله."],
 "كيف تتغيّر نظرتي إلى الفقد حين أستحضر ما وصفه الله من حال الشهداء عنده؟"),
}

